command:
T=$(mktemp -d); cp ../../../docs/assets/project-cards/memory-recall-card.svg "$T/card.svg"; cp ../../../docs/assets/project-cards/memory-recall-card.grid.json "$T/grid.json"; python3 - "$T/card.svg" "$T/grid.json" <<'PY'
import json,re,subprocess,sys,pathlib
svg=pathlib.Path(sys.argv[1]); man=pathlib.Path(sys.argv[2])
def read_vals():
    s=svg.read_text()
    def one(pat):
        m=re.search(pat, s)
        if not m:
            raise SystemExit('missing '+pat)
        return float(m.group(1))
    return {
      'shell': one(r'<rect x="680" y="([^"]+)" width="760" height="84" rx="42" class="query-shell"'),
      'icon': one(r'<g transform="translate\(718 ([^\)]+)\)" aria-hidden="true" fill="none" stroke="#93a289"'),
      'text': one(r'<text x="778" y="([^"]+)" class="sans query-text r1"')
    }
before=read_vals()
m=json.loads(man.read_text())
for r in m['rows']:
    if r['name']=='response':
        r['y'] += 20
        r['text_baseline_offset'] = before['text'] - before['shell']
man.write_text(json.dumps(m))
subprocess.run(['../run.sh','place',str(svg),str(man)], check=True)
after=read_vals()
deltas={k: round(after[k]-before[k], 1) for k in before}
if deltas == {'shell': 20.0, 'icon': 20.0, 'text': 20.0}:
    print('LABEL_UNIT_MOVE_OK', deltas)
else:
    print('LABEL_UNIT_MOVE_FAIL', deltas)
    raise SystemExit(1)
PY
rc=$?; rm -rf "$T"; exit $rc
